import sys

def main():
    n = int(sys.stdin.readline())
    perm = list(map(int, sys.stdin.readline().split()))

    elements = set(perm)
    found = False

    for i in range(n):
        a = perm[i]
        for j in range(n):
            if i == j:
                continue
            b = perm[j]
            val = a / b
            if val in elements and 1 <= val <= n:
                found = True
                break
        if found:
            break

    print("YES" if found else "NO")

main()
